import{_ as e,o as t,c as s,a2 as r}from"./chunks/framework.doxMM-x8.js";const p=JSON.parse('{"title":"现有平台能力","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/guides/platform","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"guides/platform.md","filePath":"guides/platform.md"}'),i={name:"guides/platform.md"};function o(n,a,d,l,c,b){return t(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="现有平台能力" tabindex="-1">现有平台能力 <a class="header-anchor" href="#现有平台能力" aria-label="Permalink to &quot;现有平台能力&quot;">​</a></h1><p>目标：在 Lab Word 开发中复用已有平台入口，并理解它们与实验室业务的边界。先完成<a href="./../getting-started/quickstart">快速开始</a>。</p><h2 id="从真实接口开始" tabindex="-1">从真实接口开始 <a class="header-anchor" href="#从真实接口开始" aria-label="Permalink to &quot;从真实接口开始&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/auth/session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/openapi.json</span></span></code></pre></div><p>匿名 session 请求应返回 401；OpenAPI 应返回 JSON，并标识 <code>Lab Word API</code>。已登录页面通过 SDK 使用 Session；业务写请求沿用可信 Origin 与 CSRF，不能用客户端按钮可见性代替后端授权。</p><h2 id="源码与职责" tabindex="-1">源码与职责 <a class="header-anchor" href="#源码与职责" aria-label="Permalink to &quot;源码与职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>公开源码入口</th><th>Lab 的责任</th></tr></thead><tbody><tr><td>注册、会话、密码重置</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer">Identity</a></td><td>复用当前 User 与 Session</td></tr><tr><td>企业成员与角色</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer">Organization</a></td><td>定义设备资源的具体访问资格</td></tr><tr><td>文件与清理</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer">Files</a></td><td>未来明确资产所有权；M0 本地导入不调用上传</td></tr><tr><td>后台任务、审计、通知</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Jobs</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/crates/app/src/modules/audit/mod.rs" target="_blank" rel="noreferrer">Audit</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/crates/app/src/modules/notifications/mod.rs" target="_blank" rel="noreferrer">Notifications</a></td><td>定义业务 Handler、审计语义和通知目标</td></tr><tr><td>知识库</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/crates/app/src/modules/knowledge/mod.rs" target="_blank" rel="noreferrer">Knowledge</a></td><td>保留现有功能，与设备模型区分</td></tr></tbody></table><p>当前 HTTP 请求、操作名与响应以<a href="./../reference/api">生成 API</a>为准，设置以<a href="./../reference/config">配置参考</a>为准。平台能力不代表设备遥测、IoT 接入或控制已经存在。</p><h2 id="验证失败边界" tabindex="-1">验证失败边界 <a class="header-anchor" href="#验证失败边界" aria-label="Permalink to &quot;验证失败边界&quot;">​</a></h2><p>从仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:frontend</span></span></code></pre></div><p>后端检查启动隔离服务，真实验证注册、会话、拒绝与失效；需要 Docker。前端测试在 HTTP 边界使用 MSW，不证明真实数据库与存储集成。按<a href="./../testing/feedback-loop">测试指南</a>选择变更涉及的入口。</p><h2 id="运维入口" tabindex="-1">运维入口 <a class="header-anchor" href="#运维入口" aria-label="Permalink to &quot;运维入口&quot;">​</a></h2><p>现有部署定义为 <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/compose.production.yaml" target="_blank" rel="noreferrer">compose.production.yaml</a>，配置示例为 <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/deploy/production/env.production.example" target="_blank" rel="noreferrer">env.production.example</a>。<a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/justfile" target="_blank" rel="noreferrer">justfile</a>提供显式迁移、部署、备份及独立恢复入口。先检查当前脚本和环境配置；此页不声明 Lab 生产发布已完成。</p><hr><p>源码版本：<code>e6f80f5edb69</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/e6f80f5edb69c802ca46bdb296bff2fce04c38c1/docs/guides/platform.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,16)])])}const f=e(i,[["render",o]]);export{p as __pageData,f as default};
